import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"61、【中孚】 兑下巽上","description":"周易尚氏学 - 61、【中孚】 兑下巽上","frontmatter":{"title":"61、【中孚】 兑下巽上","description":"周易尚氏学 - 61、【中孚】 兑下巽上"},"headers":[],"relativePath":"zh/classics/shangshi/066.md","filePath":"zh/classics/shangshi/066.md"}'),s={name:"zh/classics/shangshi/066.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_61、【中孚】-兑下巽上" tabindex="-1">61、【中孚】 兑下巽上 <a class="header-anchor" href="#_61、【中孚】-兑下巽上" aria-label="Permalink to “61、【中孚】 兑下巽上”">​</a></h1><p>上卦节。节信也。节何以为信。以中爻两震竹相合。中孚初至五象与节同。仍两竹相合。而在中四爻。故曰中孚。孚信也。归藏曰大明。大明者离日晋顺而丽乎大明是也。是以小过为坎。大明为离。取义与周易微异也。巽为豚为鱼。鱼象人知之。豚即失传。岂知后初云。赢豕孚滴（左足）躅。即以巽为豕。易林在有之后。牝豕无。假（左犬）旅之遁彭生为为豕。皆以巽为豕。盖坎为豕以其隐伏。巽为伏。故亦为京。而中孚正覆巽。豚鱼合居于中。故吉。坤为大川。震为舟为虚为木。五履重阴。乘震舟之上。故曰利涉大川。传释曰乘木舟虚。按涣传云。乘木有功。乘木即乘舟。又益传云。木道乃行。木亦谓舟。据王应麟所辑郑注云。舟谓集板如今船。原作自。阮校诗谷风正义云。自当为船。空大木为之曰虚。即古又名曰虚。总名皆曰舟。据郑注木舟虚三者。平列为义。皆船也。利贞。传释为应乎天。五天位。三四皆阴爻。阳得阴则通。阴顺阳故曰应乎天。</p><p>彖曰。中孚。柔在内而刚得中。说而巽。孚乃化邦也。豚鱼吉。信及豚鱼也。利涉大川。乘木舟虚也。中孚以利贞。乃应乎天也。</p><p>中爻艮为邦。艮邦震舟震象皆失传。详焦氏易诂。</p><p>象曰。泽上有风。中孚君子以议狱缓死。</p><p>玉篇狱谓之牢。又谓圜土。中爻艮止为狱。两艮相合。则圜狱也。震为言故议狱。兑为毁折。故曰死。议狱缓死。欲孚及罪人而向善也。</p><p>初九。虞吉。有它不燕。</p><p>仪礼士虞礼注。释虞为安。初阳遇阳不宜动。与节初同。节初九不出户庭无咎。即谓安吉也。它谓四。四巽为陨落。有它谓不安于初。不顾二阻。而它往应四。则不燕也。燕与宴通。亦安也。兑为燕。四巽兑覆。故曰不燕。易林小畜之兑随之革。皆曰燕雀衔茅。则皆以兑为燕。除易林外。他无用者。故易林为易象数（上草）。</p><h3 id="象曰。初九虞吉。志未变也。" tabindex="-1">象曰。初九虞吉。志未变也。 <a class="header-anchor" href="#象曰。初九虞吉。志未变也。" aria-label="Permalink to “象曰。初九虞吉。志未变也。”">​</a></h3><p>巽为志。志未变。言安于初而不应四。</p><p>九二。鸣鹤在阴。其子和之。我有好爵。吾与尔靡之。</p><p>震为鹤。为鸣。为子。阴山阴。二至五正反震。下震鹤。鸣于山阴。三至五震反。如声回答。若相和然。故曰其子和之。其子谓覆震。非互震。判然二物也。易林大有之屯云。嗟嗟所言。嗟嗟对语也。屯初至五亦正覆震相对。与中孚同。又同人之中孚云。衣裳颠倒。震为衣。三至五震覆。故曰颠倒。涣之中孚云。闻言不信。震言。三至五震覆。故不信。不信取其相反。子和取其相对。仍同也。而二至五亦正反艮。艮纳丙为山阳。下二至四艮覆。则山阴矣。而二正当其处。故曰鸣鹤在阴。易林颐之中孚云。熊罴豺狼。在山阴阳。正覆良故既曰熊罴。又曰豺狼。上艮为山阳。下覆艮为山阴也。故曰在山阴阳。易林释此语。可谓明白矣。山阴之义。知者甚鲜。后独茹敦和以阴为山阴。而取义于兑。兑者艮之反。艮山阳。兑山阴。义不本易林。而取义与易林同。故夫有清一代之易家。主张自己。不随声附和者。莫茹氏若也。爵。说文饮器。酒尊也。震为尊为爵为嘉。故曰好爵。正覆震相对。故曰吾与尔靡之。孟喜云。靡共也。贞我悔彼。尔谓五。言二五共此爵也。</p><h3 id="象曰。其子和之。中心愿也。" tabindex="-1">象曰。其子和之。中心愿也。 <a class="header-anchor" href="#象曰。其子和之。中心愿也。" aria-label="Permalink to “象曰。其子和之。中心愿也。”">​</a></h3><p>巽为心志。鸣和全在中四爻。故曰中心愿。</p><p>六三。得敌。或鼓或罢。或泣或歌。</p><p>子夏传三与四为敌。故曰得敌。荀爽曰。三四俱阴。故称敌也。中四爻艮相反复。震为鼓。艮止故罢。罢疲通音婆。下与歌叶。诸家或作罢音非也。震为歌。震反则泣矣。与艮为山阳。艮反为山阴义同也。盖三不当位而遇敌。故不常如此也。得敌与颐二之失类。艮之敌应。为易义之根本。所关甚大。乃得敌韩子夏与苟知之。失类则无知者。致阴遇阴阳遇阳之处皆失解。可喟也。</p><h3 id="象曰。或鼓或罢。位不当也。" tabindex="-1">象曰。或鼓或罢。位不当也。 <a class="header-anchor" href="#象曰。或鼓或罢。位不当也。" aria-label="Permalink to “象曰。或鼓或罢。位不当也。”">​</a></h3><p>义见前。</p><p>六四。月既望。马匹亡。无咎。</p><p>兑为月。十五日日月望。乾象月盈甲。十六日平明。巽象月退辛。六四巽主。故曰既望。既王弼作几。孟、荀皆作既。孟云十六日也。作既于巽象方切。震为马。四匹在初。马匹亡。言不应初而承上也。承阳故无咎。</p><p>站长：孟、荀可能是指孟喜和荀爽，他们是西汉时期的易学家。应该当作「既望」，巽也为月始缺，如小畜「既雨既处...月既望」同理。</p><h3 id="象曰。马匹亡。绝类上也。" tabindex="-1">象曰。马匹亡。绝类上也。 <a class="header-anchor" href="#象曰。马匹亡。绝类上也。" aria-label="Permalink to “象曰。马匹亡。绝类上也。”">​</a></h3><p>阴阳相遇方为类。旧解皆以阴遇阴为类。故全易类宇皆失诂。绝者决也。言四遇三敌。不能应初。类上即承上也。</p><p>九五。有孚挛如。无咎。</p><p>五下乘重阴。得类。故曰有孚。言孚于二阴也。挛系也。恋也。前书李夫人传。挛挛顾念我。有孚挛如者。言系挛三四也。五得位。故无咎。</p><h3 id="象曰。有孕挛如。位正当也" tabindex="-1">象曰。有孕挛如。位正当也 <a class="header-anchor" href="#象曰。有孕挛如。位正当也" aria-label="Permalink to “象曰。有孕挛如。位正当也”">​</a></h3><p>五既中且正。</p><p>上九。翰音登于天。贞凶。</p><p>曲礼曰。鸡曰翰音。巽为鸡。为高。居翼卜又居卦之极上。故曰翰音登于天。上应在三。三震为翰为音也。巽下陨。故贞凶。王注翰高飞也。飞音者。音飞而实不至之谓也。居卦之上。华美外扬。虚声无实。故不可久长。</p><h3 id="象曰。翰青登于天。何可长也。" tabindex="-1">象曰。翰青登于天。何可长也。 <a class="header-anchor" href="#象曰。翰青登于天。何可长也。" aria-label="Permalink to “象曰。翰青登于天。何可长也。”">​</a></h3><p>穷上失位。下虚。故不长。翰音取象皆在应。非只巽鸡。易无一字不由象生。观此益信矣。震翰象失传。详焦氏易诂。</p>',31)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
